# Loop through all log files and count severities for all periods
for file in *.log; do
    file_date=$(echo "$file" | grep -oE "[0-9]{4}-[0-9]{2}-[0-9]{2}");

    E=$(grep -c "ERROR" "$file");
    W=$(grep -c "WARNING" "$file");
    I=$(grep -c "INFO" "$file");

    # --- Total Count ---
    C_E["total"]=$((C_E["total"] + E));
    C_W["total"]=$((C_W["total"] + W));
    C_I["total"]=$((C_I["total"] + I]));

    # --- Date Range Checks ---
    # Last 30 Days: >= 2025-07-14 AND <= 2025-08-12
    if [[ "$file_date" >= "2025-07-14" && "$file_date" <= "2025-08-12" ]]; then
        C_E["last_30_days"]=$((C_E["last_30_days"] + E));
        C_W["last_30_days"]=$((C_W["last_30_days"] + W));
        C_I["last_30_days"]=$((C_I["last_30_days"] + I));
    fi

    # Last 7 Days: >= 2025-08-06 AND <= 2025-08-12
    if [[ "$file_date" >= "2025-08-06" && "$file_date" <= "2025-08-12" ]]; then
        C_E["last_7_days"]=$((C_E["last_7_days"] + E));
        C_W["last_7_days"]=$((C_W["last_7_days"] + W));
        C_I["last_7_days"]=$((C_I["last_7_days"] + I));
    fi

    # Month to Date: >= 2025-08-01 AND <= 2025-08-12
    if [[ "$file_date" >= "2025-08-01" && "$file_date" <= "2025-08-12" ]]; then
        C_E["month_to_date"]=$((C_E["month_to_date"] + E));
        C_W["month_to_date"]=$((C_W["month_to_date"] + W));
        C_I["month_to_date"]=$((C_I["month_to_date"] + I));
    fi

    # Today: == 2025-08-12
    if [[ "$file_date" == "2025-08-12" ]]; then
        C_E["today"]=$((C_E["today"] + E));
        C_W["today"]=$((C_W["today"] + W));
        C_I["today"]=$((C_I["today"] + I));
    fi

done

